enum AdvanceMode { MANUAL, AUTO, FAST }


func run() -> String:
	var current_mode: AdvanceMode = AdvanceMode.AUTO
	var result: String = ""
	match current_mode:
		AdvanceMode.MANUAL:
			result = "manuale"
